sysevent_script_action.script:
try {

	var eventData = JSON.parse(event.parm2);
    var tipProcesare = eventData.type;              
    var instr = eventData.instructions;
	var promptAi = "Process the invoice with the sys_id " + current.getUniqueValue() + ". ";
    promptAi += "The required processing type is: " + tipProcesare + ". ";

    if (instr && instr.trim() !== '') {
        promptAi += "Please follow these additional instructions from the user: " + instr;
    }

    var apiKey = 'sk-lRXpy4XnxMsJE04NfAgPNNDMtZlRIiJZp2SxdC9s3SM'; 
    var endpoint = 'https://21bc-2a02-2f0f-b109-dd00-c972-f432-30e0-f1b5.ngrok-free.app/api/v1/run/987ac07e-4831-4353-88e6-380efdbaa5f1';

    var payload = {
        "output_type": "chat",
        "input_type": "chat",
        "input_value": promptAi,
        "session_id": gs.generateGUID() 
    };

	current.work_notes = "[LangFlow AI] Cererea a fost trimisă către agent. Se rulează modul: " + tipProcesare + "...";
    current.update();
    var request = new sn_ws.RESTMessageV2();
    request.setEndpoint(endpoint);
    request.setHttpMethod('POST');
    request.setRequestHeader("Content-Type", "application/json");
    request.setRequestHeader("x-api-key", apiKey);
    request.setRequestBody(JSON.stringify(payload));
	request.setHttpTimeout(540000);
    var response = request.execute();
    var responseBody = response.getBody();
    var httpStatus = response.getStatusCode();


    if (httpStatus == 200) {
        var parsedResponse = JSON.parse(responseBody);
        var extractedMessage = "";

        try {

            var agentSteps = parsedResponse.outputs[0].outputs;

            for (var i = 0; i < agentSteps.length; i++) {
                if (agentSteps[i].results && agentSteps[i].results.message && agentSteps[i].results.message.data) {
                    var textOutput = agentSteps[i].results.message.data.text;

                    if (textOutput) {
                        extractedMessage += textOutput + "\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n";
                    }
                }
            }            
            extractedMessage = extractedMessage.trim().replace(/━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━$/, "").trim();

        } catch (e) {
            extractedMessage = " Eroare la parsarea textului din LangFlow. Mesaj brut:\n" + responseBody;
        }

        current.work_notes = "Răspuns Langflow primit cu succes:\n" + extractedMessage;
    } else {
        current.work_notes = "Eroare de la Langflow. Cod HTTP: " + httpStatus + "\nDetalii: " + responseBody;
    }

    current.update();

} catch (ex) {
    current.work_notes = "A apărut o eroare de sistem la apelarea Langflow: " + ex.message;
    current.update();
}
